Header.prototype.syncState = function (isVisible) {
  this.$menuButton.classList.toggle('govuk-header__menu-button--open', isVisible)
  this.$menuButton.setAttribute('aria-expanded', isVisible)
  // Determine if menu should be hidden from assistive tech
  var hidden = !isVisible;
  // If menu button is not displayed (desktop), menu should be visible
  if (this.$menuButton && window.getComputedStyle(this.$menuButton).display === 'none') {
    hidden = false;
  }
  this.$menu.setAttribute('aria-hidden', hidden);
}
